const catalogAvailability={available:'Доступно',out_of_stock:'Закончилось / недоступно',preorder:'Под заказ',unknown:'Уточнить у сотрудника'};
let starterPreview=null;
async function openCatalogStarter(){try{starterPreview=await api('catalog_starter_preview');modal('Пример каталога: '+starterPreview.label,'<p class="notice">Это демонстрационные позиции с примерными ценами и наличием. Бот будет прямо сообщать, что это пример. Перед работой с клиентами проверьте сведения и выберите в карточках «Проверено — реальные данные». Продажи и физические остатки не создаются.</p><form onsubmit="applyCatalogStarter(event)"><div class="tablewrap"><table><thead><tr><th>Добавить</th><th>Позиция</th><th>Цена</th><th>Наличие в примере</th></tr></thead><tbody>'+starterPreview.rows.map(x=>'<tr><td><input type="checkbox" name="starter_key" value="'+esc(x.key)+'" aria-label="Добавить '+esc(x.item_name)+'" checked></td><td class="wrap"><b>'+esc(x.item_name)+'</b><small>'+esc(x.category)+' · '+esc(x.details.unit)+'</small></td><td>'+money(x.item_price)+'</td><td>'+esc(catalogAvailability[x.details.availability])+'</td></tr>').join('')+'</tbody></table></div><p class="hint">Одинаковые названия будут пропущены. Ваши позиции и цены не перезаписываются. Набор относится только к текущей сфере бизнеса.</p><div class="actions"><button class="btn" type="submit">Добавить выбранные примеры</button></div></form>')}catch(e){toast(e.message)}}
async function applyCatalogStarter(ev){ev.preventDefault();const b=ev.target.querySelector('[type=submit]');b.disabled=true;try{const keys=[...ev.target.querySelectorAll('[name=starter_key]:checked')].map(x=>x.value);const r=await api('catalog_starter_apply',{type:starterPreview.type,keys});$('modal').close();await reload();render();toast('Добавлено: '+r.count+'. Уже были: '+r.skipped)}catch(e){toast(e.message)}finally{b.disabled=false}}
function catalogDetailFields(){return opsCatalogFields()+'<div class="field"><label for="f_availability">Наличие для ответов бота</label><select id="f_availability" name="availability">'+Object.entries(catalogAvailability).map(([k,v])=>'<option value="'+k+'" '+(k==='unknown'?'selected':'')+'>'+esc(v)+'</option>').join('')+'</select></div>'+field('unit','Объём / единица / длительность','text','','maxlength="80"')+textfield('description','Описание и условия','Состав, ограничения, что входит в цену')+field('aliases','Как ещё называют товар / услугу','text','','maxlength="400"')+'<div class="field span2"><label for="f_data_mode">Достоверность сведений</label><select id="f_data_mode" name="data_mode"><option value="live">Проверено — реальные данные</option><option value="demo">Демонстрационный пример</option></select></div>'}
function catalogCustomerCell(x){const d=x.details||{},other=d.business_type&&d.business_type!==(state.profile||BOOT.profile).type;return '<b style="display:block;min-width:150px">'+esc(x.item_name)+'</b><small style="display:block;margin-top:5px;line-height:1.5">'+esc(d.description||'')+'</small>'+(d.data_mode==='demo'?'<span class="badge">Пример</span> ':'')+(other?'<span class="badge">Другая сфера — скрыто от бота</span>':'')}

function openCatalog(){modal(tr('Новая позиция','Жаңа тауар'),'<form onsubmit="submitForm(event,\'catalog\')"><div class="fields">'+field('item_name','Наименование','text','','required maxlength="180"')+field('category','Категория','text','Основное','required')+field('item_price','Цена продажи, ₸','number','','required min="0.01" step="0.01"')+field('item_cost','Себестоимость, ₸','number','0','min="0" step="0.01" required')+field('units_sold','Продано за период, шт.','number','0','min="0" step="1" required')+catalogDetailFields()+'</div><p class="hint">Продано — фактические продажи, а не остаток. Наличие для бота отмечается отдельно; обновляйте его, когда позиция заканчивается. Для услуги «Доступно» означает, что вы её оказываете; время записи подтверждает сотрудник.</p><div class="actions"><button class="btn" type="submit">Сохранить позицию</button></div></form>')}
function openClient(){modal('Новый клиент','<form onsubmit="submitForm(event,\'save\',\'clients\')"><div class="fields">'+field('name','Имя / компания','text','','required maxlength="180"')+field('phone','Телефон','tel','','required')+field('email','Email','email')+select('status','Статус',['Новый','В работе','Постоянный'])+textfield('note','Заметка')+'</div><div class="actions"><button class="btn" type="submit">Сохранить клиента</button></div></form>')}
function totals(){const c=state.catalog||[];return {revenue:c.reduce((s,x)=>s+x.item_price*x.units_sold,0),cost:c.reduce((s,x)=>s+x.item_cost*x.units_sold,0),sold:c.reduce((s,x)=>s+Number(x.units_sold),0),expense:(state.expenses||[]).reduce((s,x)=>s+Number(x.data.amount),0)}}
function legacyDashboard(){const t=totals(),cards=[['Выручка по каталогу',money(t.revenue),'По внесённым продажам'],['Валовая прибыль',money(t.revenue-t.cost),'Выручка минус себестоимость'],['Товары и услуги',(state.catalog||[]).length,'Позиций в вашем каталоге'],['Клиенты',(state.clients||[]).length,'В вашей клиентской базе']];return head(tr('Ваш бизнес. На шаг впереди.','Бизнесіңіз бір қадам алда.'),tr('Всё для ежедневной работы — в одном пространстве.','Күнделікті жұмысқа қажеттінің бәрі бір жерде.'),'<a class="btn" href="#catalog">＋ '+tr('Добавить продажи','Сатуды қосу')+'</a>')+'<div class="grid stats">'+cards.map(c=>'<div class="stat"><label>'+c[0]+'</label><strong>'+esc(c[1])+'</strong><small>'+c[2]+'</small></div>').join('')+'</div><div class="grid twocol"><section class="card assistant"><span class="badge">✳ '+tr('Ваш бизнес-ассистент','Бизнес көмекшіңіз')+'</span><h2>'+tr('Меньше рутины.<br>Больше возможностей.','Аз жұмыс.<br>Көп мүмкіндік.')+'</h2><p>'+tr('Подготовьте предложение, придумайте пост или разберите расходы. На русском и қазақша.','Ұсыныс дайындаңыз, пост жазыңыз немесе шығындарды талдаңыз.')+'</p><div class="chips"><button class="chip" onclick="location.hash=\'marketing\'">✧ Написать пост</button><button class="chip" onclick="location.hash=\'sales\'">▧ Подготовить КП</button><button class="chip" onclick="location.hash=\'finance\'">↗ Разобрать расходы</button></div><form class="composer" onsubmit="event.preventDefault();sessionStorage.setItem(\'aulieata.prompt\',this.q.value);location.hash=\'sales\'"><input name="q" required aria-label="Задача для ИИ" placeholder="'+tr('С чего начнём сегодня?','Бүгін неден бастаймыз?')+'"><button aria-label="Отправить задачу">↗</button></form></section><section class="card"><h2>'+tr('Сегодня в вашем бизнесе','Бизнесіңіздегі бүгінгі күн')+'</h2><p>Только данные вашего рабочего пространства.</p><div class="row"><div><b>Ближайшие записи</b><small>Подтверждённые бронирования</small></div><a href="#bookings" class="badge">'+(state.bookings||[]).filter(b=>b.status==='confirmed'&&b.starts_at.slice(0,10)>=today()).length+' ↗</a></div><div class="row"><div><b>Расходы к учёту</b><small>За все загруженные даты</small></div><a href="#finance"><b>'+money(t.expense)+'</b></a></div><div class="row"><div><b>Сохранённые документы</b><small>КП, счета, сметы и черновики</small></div><a href="#documents" class="badge">'+(state.documents||[]).length+' ↗</a></div></section></div><div class="sectiontitle"><h2>'+tr('Инструменты для роста','Өсуге арналған құралдар')+'</h2><span class="hint">Инструменты вашей сферы · RU / ҚАЗ</span></div><div class="grid modulegrid">'+[['sales','✳','ИИ-Продажи и Voice','Ответы клиентам, КП и счета'],['marketing','◇','Контент-студия','SMM, Reels и карточки Kaspi'],['finance','↗','Финансы','Учёт расходов и анализ данных'],['reputation','◎','AI TazaPary','Разбор отзывов и проекты ответов'],['toi','❋','Той-смета','Гости, продукты и бюджет'],['grants','⌘',(state.profile||BOOT.profile).type==='garden'?'Гранты и Agro':'Гранты и субсидии',(state.profile||BOOT.profile).type==='garden'?'Бизнес-планы и фото растений':'Поддержка бизнеса и бизнес-планы'],['legal','♜','Правовой щит','Договоры и контроль лимитов'],['hr','♙','HR и обучение','Интервью и база знаний']].filter(c=>visibleModules().some(m=>m[0]===c[0])).map(c=>'<a href="#'+c[0]+'" class="card module"><span class="arrow">↗</span><div class="iconbox">'+c[1]+'</div><h3>'+c[2]+'</h3><p>'+c[3]+'</p></a>').join('')+'</div>'}
function catalog(){let c=state.catalog||[],t=totals();return head(tr('Каталог и продажи','Каталог және сату'),'Товары, услуги, цены и наличие — единый источник ответов вашего бота.','<div class="actions" style="margin:0"><button class="btn light" onclick="openCatalogStarter()">Пример для моей сферы</button><button class="btn light" onclick="openSmartImport(\'catalog\')">Импорт с ИИ</button><button class="btn" onclick="openCatalog()">＋ Добавить позицию</button></div>')+'<div class="grid stats">'+[['Выручка',money(t.revenue)],['Валовая прибыль',money(t.revenue-t.cost)],['Маржа',t.revenue?((t.revenue-t.cost)/t.revenue*100).toFixed(1)+'%':'—'],['Продано',t.sold+' шт.']].map(x=>'<div class="stat"><label>'+x[0]+'</label><strong>'+x[1]+'</strong><small>По данным каталога</small></div>').join('')+'</div>'+(c.some(x=>x.details?.data_mode==='demo')?'<div class="notice">В каталоге есть демонстрационные позиции. Бот обозначает их как пример. Отредактируйте цены и наличие, затем отметьте «Проверено — реальные данные». Себестоимость 0 означает, что вы её ещё не внесли.</div>':'')+'<div class="card"><div class="actions" style="margin:0 0 16px"><input class="search" id="catSearch" aria-label="Поиск товара" placeholder="Поиск по названию…" oninput="filterTable(this.value)"><button class="btn light" onclick="exportCatalog()">Экспорт CSV</button></div>'+(c.length?'<div class="tablewrap"><table id="dataTable"><thead><tr><th>Наименование</th><th>Категория</th><th>Цена / единица</th><th>Наличие</th><th>Себестоимость</th><th>Продано</th><th>Выручка</th><th>Валовая прибыль</th><th></th></tr></thead><tbody>'+c.map(x=>'<tr><td class="wrap">'+catalogCustomerCell(x)+'</td><td>'+esc(x.category)+'</td><td>'+money(x.item_price)+'<small style="display:block;margin-top:5px">'+esc(x.details?.unit||'')+'</small></td><td>'+esc(catalogAvailability[x.details?.availability||'unknown'])+'</td><td>'+money(x.item_cost)+'</td><td>'+Number(x.units_sold)+'</td><td>'+money(x.item_price*x.units_sold)+'</td><td>'+money((x.item_price-x.item_cost)*x.units_sold)+'</td><td><button class="btn light small" onclick="editCatalog('+x.id+')">Изменить</button> <button class="btn light small" onclick="archiveCatalog('+x.id+')">В архив</button></td></tr>').join('')+'</tbody></table></div>':empty('Каталог пока пуст. Добавьте первую позицию.'))+'</div>'}
function filterTable(q){document.querySelectorAll('#dataTable tbody tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q.toLowerCase()))}
function clients(){const rows=state.clients||[];return head(tr('Клиенты','Клиенттер'),'Клиентская база хранится отдельно для вашего аккаунта.','<button class="btn" onclick="openClient()">＋ Новый клиент</button>')+'<section class="card"><input class="search" placeholder="Поиск клиента…" aria-label="Поиск клиента" oninput="filterTable(this.value)"><div class="tablewrap"><table id="dataTable"><thead><tr><th>Клиент</th><th>Телефон</th><th>Email</th><th>Статус</th><th>Заметка</th><th></th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+esc(r.data.name)+'</td><td>'+esc(r.data.phone)+'</td><td>'+esc(r.data.email)+'</td><td><span class="badge">'+esc(r.data.status)+'</span></td><td class="wrap">'+esc(r.data.note)+'</td><td><button class="btn light small" onclick="archiveRecord('+r.id+')">В архив</button></td></tr>').join('')+'</tbody></table></div>'+(!rows.length?empty('Добавьте клиента, чтобы начать работу с базой.'):'')+'</section>'}
async function archiveRecord(id){try{await api('archive',{id});await reload();render();toast('Запись перенесена в архив')}catch(e){toast(e.message)}}
function legacyBookings(){return head(tr('Онлайн-запись','Онлайн жазылу'),'Бронирование фиксированного времени с защитой от повторной записи.')+'<div class="notice">Встроенный календарь работает в часовом поясе Казахстана (UTC+5). Ресурс — конкретный стол, мастер или кабинет. Google Calendar пока не подключён. Одна запись занимает выбранный слот; длительность услуги учитывайте при выборе времени.</div><div class="grid twocol"><section class="card"><h2>Новая запись</h2><form onsubmit="submitForm(event,\'book\')"><div class="fields">'+field('client','Имя клиента','text','','required')+field('phone','Телефон','tel')+field('service','Услуга','text','','required placeholder="Например, пробный урок"')+field('resource','Мастер / стол / кабинет','text','','required placeholder="Например, Стол 1"')+field('starts_at','Дата и время, UTC+5','datetime-local','','required')+'</div><div class="actions"><button class="btn" type="submit">Забронировать</button></div></form></section><section class="card"><h2>Календарь записей</h2>'+((state.bookings||[]).length?(state.bookings||[]).map(b=>'<div class="row"><div><b>'+esc(b.client)+' · '+esc(b.service)+'</b><small>'+esc(b.starts_at.slice(0,16))+' · '+esc(String(b.resource).replace(/^cancelled-\d+-/,''))+'<br>'+esc(b.phone)+' · '+(b.status==='confirmed'?'Подтверждено':'Отменено')+'</small></div>'+(b.status==='confirmed'?'<div><button class="btn light small" onclick="downloadIcs('+b.id+')">.ics</button> <button class="btn light small" onclick="cancelBooking('+b.id+')">Отменить</button></div>':'')+'</div>').join(''):empty('Здесь появятся ваши бронирования.'))+'</section></div>'}
async function cancelBooking(id){try{await api('cancel_booking',{id});await reload();render();toast('Запись отменена. Слот освобождён.')}catch(e){toast(e.message)}}
function dl(text,name,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
function downloadIcs(id){const b=state.bookings.find(x=>Number(x.id)===id),d=new Date(b.starts_at.replace(' ','T')+'+05:00'),end=new Date(+d+30*60000),fmt=v=>v.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const clean=v=>String(v).replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/[,;]/g,' ');dl('BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//AulieAta//Bookings//RU\r\nBEGIN:VEVENT\r\nUID:'+id+'-'+BOOT.biz.replace(/[^a-z0-9]/gi,'')+'@itudron.ru\r\nDTSTAMP:'+fmt(new Date())+'\r\nDTSTART:'+fmt(d)+'\r\nDTEND:'+fmt(end)+'\r\nSUMMARY:'+clean(b.service+' / '+b.client)+'\r\nDESCRIPTION:'+clean(b.resource+' '+b.phone)+'\r\nEND:VEVENT\r\nEND:VCALENDAR','booking-'+id+'.ics','text/calendar;charset=utf-8')}
