function aiWorkspace(type){let c={...aiConfigs[type],options:[...aiConfigs[type].options]},profile=state.profile||BOOT.profile;if(type==='grants'&&profile.type!=='garden'){c.options=c.options.filter(x=>!x.startsWith('Agro:'));c.title='Гранты и субсидии';c.sub='Программы поддержки и бизнес-план для вашей сферы.';c.placeholder='Опишите проект, район, бюджет и рабочие места. Вставьте условия программы для разбора.';c.note='Условия программ проверяйте на официальных сайтах. Автопоиск требует доступной квоты Google Search.'}if(type==='marketing'&&['beauty','fitness','edu','auto','finance','it','logistics','realty','services','medical'].includes(profile.type))c.options=c.options.filter(x=>x!=='Карточка Kaspi.kz');let prefix=head(c.title,c.sub),tools='';if(type==='sales')tools='<div class="actions" style="margin-bottom:20px"><button class="btn light" onclick="openInvoice()">▧ Создать счёт / КП</button></div>';if(type==='finance')tools=financeTools();if(type==='legal')tools=taxTool();if(type==='hr')tools=knowledgeTool();if(type==='grants')tools='<div class="card" style="margin-bottom:20px"><h3>Официальные источники</h3><p><a href="https://damu.kz/" target="_blank" rel="noopener">Фонд Даму ↗</a> · <a href="https://www.gov.kz/" target="_blank" rel="noopener">Госпрограммы на gov.kz ↗</a></p></div>';
return prefix+tools+'<div class="notice">'+c.note+'</div><div class="grid twocol"><section class="card"><h2>'+tr('Новая задача','Жаңа тапсырма')+'</h2><form id="aiForm" onsubmit="runAI(event)"><div class="fields">'+select('task','Инструмент',c.options)+select('language','Язык ответа',['Русский','Қазақша'])+textfield('prompt','Задача и исходные данные',c.placeholder)+(type==='grants'&&profile.type==='garden'?'<div class="field span2"><label for="photo">Фото растения, JPG / PNG / WebP до 4 МБ</label><input id="photo" type="file" accept="image/jpeg,image/png,image/webp" onchange="loadPhoto(this)"><span class="hint" id="photoStatus"></span></div>':'')+(type==='legal'?'<div class="field span2"><label for="contract">Загрузить текст договора (.txt)</label><input id="contract" type="file" accept=".txt" onchange="loadText(this)"></div>':'')+'</div><p class="hint">Задача и прикреплённые данные будут переданы Google Gemini. Вставляйте только необходимые сведения.</p><div class="actions"><button type="submit" class="btn" id="aiSubmit">✳ '+tr('Создать с ИИ','ЖИ арқылы жасау')+'</button>'+(type==='sales'?'<button type="button" class="btn light" onclick="startVoice()">♩ Голосом</button>':'')+'</div><div id="aiError" role="alert"></div></form></section><section class="card"><h2>'+tr('Результат','Нәтиже')+'</h2><p>Проверьте текст перед использованием.</p><div id="aiResult" class="result" data-empty="Здесь появится ответ помощника."></div><div id="searchSources"></div><div class="actions"><button class="btn light small" onclick="copyResult()">Копировать</button><button class="btn light small" onclick="saveResult()">Сохранить</button><button class="btn light small" onclick="printResult()">PDF / печать</button><button class="btn light small" onclick="speakResult()">▷ Прочитать</button></div></section></div>'+historyView(type)}
async function runAI(ev){ev.preventDefault();let b=$('aiSubmit'),requestModule=current,resultElement=$('aiResult'),errorElement=$('aiError');b.disabled=true;b.textContent='Готовим ответ…';$('aiError').textContent='';let d=formData(ev.target),context='';if(current==='finance')context='\nДанные каталога: '+JSON.stringify(state.catalog)+'\nРасходы: '+JSON.stringify(state.expenses.map(x=>x.data));if(current==='hr'&&d.task==='Ответ по базе знаний')context='\nИспользуй только эти регламенты. Если ответа нет, скажи, что нужно уточнить у руководителя.\n'+JSON.stringify(state.knowledge.map(x=>x.data));try{const r=await api('ai',{module:current,lang:d.language==='Қазақша'?'kk':'ru',prompt:'Задача: '+d.task+'\n'+d.prompt+context,image:current==='grants'?imageData:''});if(current===requestModule&&resultElement.isConnected){lastResult=r.text;lastTitle=d.task;resultElement.textContent=lastResult;if($('searchSources'))$('searchSources').innerHTML=sourceLinks(r);}toast('Ответ готов');await reload()}catch(e){if(errorElement.isConnected){errorElement.className='error';errorElement.textContent=e.message}else toast(e.message)}finally{b.disabled=false;b.textContent=tr('✳ Создать с ИИ','✳ ЖИ арқылы жасау')}}
async function loadPhoto(input){imageData='';let f=input.files[0];if(!f)return;if(f.size>4*1024*1024||!['image/jpeg','image/png','image/webp'].includes(f.type)){input.value='';toast('Используйте JPG, PNG или WebP до 4 МБ');return}const reader=new FileReader();reader.onload=()=>{imageData=reader.result;$('photoStatus').textContent='Прикреплено: '+f.name};reader.readAsDataURL(f)}
async function loadText(input){const f=input.files[0];if(!f)return;if(f.size>100000){toast('Текстовый файл должен быть до 100 КБ');return}$('f_prompt').value=await f.text()}
function startVoice(){const R=window.SpeechRecognition||window.webkitSpeechRecognition;if(!R){toast('Голосовой ввод недоступен в этом браузере. Используйте ввод текстом.');return}let r=new R();r.lang=$('f_language').value==='Қазақша'?'kk-KZ':'ru-RU';r.interimResults=false;r.onresult=e=>{$('f_prompt').value+=' '+e.results[0][0].transcript};r.onerror=e=>toast('Голосовой ввод: '+(e.error==='not-allowed'?'разрешите микрофон в браузере':e.error));r.start();toast('Говорите. Запись остановится после паузы.')}
async function speakResult(){if(!lastResult){toast('Сначала создайте результат');return}const text=lastResult.replace(/\*\*/g,'');toast('Готовим голосовой ответ…');try{const r=await api('tts',{text});let holder=$('voicePlayer');if(!holder){holder=document.createElement('div');holder.id='voicePlayer';holder.style.marginTop='18px';const target=$('aiResult')?.parentElement;if(!target)return;target.append(holder)}holder.innerHTML='';const audio=document.createElement('audio');audio.controls=true;audio.style.width='100%';audio.src=r.audio;holder.append(audio);try{await audio.play()}catch(e){toast('Нажмите ▶ в аудиоплеере, чтобы прослушать')}if(r.truncated)toast('Озвучены первые 1200 символов результата.')}catch(e){toast(e.message)}}
async function copyResult(){if(!lastResult){toast('Сначала создайте результат');return}try{await navigator.clipboard.writeText(lastResult);toast('Скопировано')}catch(e){toast('Браузер запретил копирование. Выделите текст вручную.')}}
async function saveResult(){if(!lastResult){toast('Сначала создайте результат');return}try{await api('save',{kind:'documents',data:{name:lastTitle||'Документ',text:lastResult,type:current}});await reload();toast('Документ сохранён')}catch(e){toast(e.message)}}
function printResult(){if(!lastResult){toast('Сначала создайте результат');return}$('printArea').innerHTML='<h1>'+esc(lastTitle||'AulieAta AI')+'</h1><p>'+esc(BOOT.biz)+' · '+esc(BOOT.location)+'</p>'+esc(lastResult);window.print()}
function historyView(type){const h=(state.history||[]).filter(x=>x.data.module===type).slice(0,10);return h.length?'<div class="sectiontitle"><h2>История задач</h2></div><div class="card">'+h.map(r=>'<div class="row"><div><b>'+esc(r.data.name)+'</b><small>'+esc(r.created_at)+'</small></div><button class="btn light small" onclick="viewHistory('+r.id+')">Открыть</button></div>').join('')+'</div>':''}
function viewHistory(id){const x=state.history.find(x=>Number(x.id)===id);lastResult=x.data.text;lastTitle=x.data.name;if($('aiResult')){$('aiResult').textContent=lastResult;$('aiResult').scrollIntoView({behavior:'smooth',block:'center'})}else modal(lastTitle,'<div class="result">'+esc(lastResult)+'</div>')}

function legacyFinanceTools(){const t=totals(),ex=state.expenses||[],groups={};ex.forEach(x=>groups[x.data.category||'Другое']=(groups[x.data.category||'Другое']||0)+Number(x.data.amount));return '<div class="grid stats">'+[['Расходы',money(t.expense)],['Записей расходов',ex.length],['Валовая прибыль каталога',money(t.revenue-t.cost)],['Период расходов','Все даты']].map(x=>'<div class="stat"><label>'+x[0]+'</label><strong>'+x[1]+'</strong></div>').join('')+'</div><div class="grid twocol" style="margin-bottom:24px"><div class="card"><h2>Учёт расходов</h2><form onsubmit="submitForm(event,\'save\',\'expenses\')"><div class="fields">'+field('name','Описание','text','','required')+field('amount','Сумма, ₸','number','','required min="0.01" step="0.01"')+field('date','Дата','date',today(),'required')+field('category','Категория','text','Закупки','required')+'</div><div class="actions"><button class="btn" type="submit">Добавить расход</button></div></form><hr style="border:0;border-top:1px solid var(--line);margin:24px 0"><h3>Импорт отчёта</h3><p>CSV, XLSX или XLS из Kaspi Pay, Excel или 1С. Первый ряд — заголовки: name;amount;date;category. Проверьте расходы перед подтверждением. До 1000 строк.</p><div class="actions"><button class="btn light small" onclick="dl(\'name;amount;date;category\\nЗакупка молока;15000;2026-10-17;Сырье\\n\',\'expenses-template.csv\',\'text/csv;charset=utf-8\')">Скачать шаблон</button><label class="btn light small" for="csvFile">Выбрать CSV / Excel</label><input id="csvFile" type="file" accept=".csv,.xlsx,.xls" style="display:none" onchange="importCSV(this)"></div></div><div class="card"><h2>Структура расходов</h2>'+(Object.keys(groups).length?Object.entries(groups).sort((a,b)=>b[1]-a[1]).map(([k,v])=>'<div class="row"><div style="width:100%"><div style="display:flex;justify-content:space-between;margin-bottom:9px"><b>'+esc(k)+'</b><b>'+money(v)+'</b></div><div class="bar"><span style="width:'+(t.expense?v/t.expense*100:0)+'%"></span></div></div></div>').join(''):empty('Добавьте расходы или импортируйте отчёт.'))+'<div class="actions"><button class="btn light small" onclick="exportExpenses()">Экспорт CSV</button></div></div></div><details class="card" style="margin-bottom:24px"><summary>Журнал расходов ('+ex.length+')</summary><div class="tablewrap"><table><thead><tr><th>Дата</th><th>Описание</th><th>Категория</th><th>Сумма</th><th></th></tr></thead><tbody>'+ex.map(x=>'<tr><td>'+esc(x.data.date)+'</td><td class="wrap">'+esc(x.data.name)+'</td><td>'+esc(x.data.category)+'</td><td>'+money(x.data.amount)+'</td><td><button class="btn light small" onclick="archiveRecord('+x.id+')">В архив</button></td></tr>').join('')+'</tbody></table></div></details>'}
let importRows=[];
function parseCSV(text){text=text.replace(/^\uFEFF/,'');const first=text.split(/\r?\n/)[0],delim=first.includes(';')?';':',',rows=[];let row=[],val='',quote=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){val+='"';i++}else quote=!quote}else if(c===delim&&!quote){row.push(val);val=''}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(val);if(row.some(v=>v.trim()))rows.push(row);row=[];val=''}else val+=c}if(quote)throw Error('Не закрыты кавычки в CSV');row.push(val);if(row.some(v=>v.trim()))rows.push(row);return rows}
async function importCSV(input){try{let file=input.files[0];if(!file)return;if(file.size>2000000)throw Error('Файл должен быть до 2 МБ');let rows=await readImportRows(file),headers=rows.shift().map(v=>v.trim().toLowerCase()),aliases={name:['name','описание','наименование'],amount:['amount','сумма'],date:['date','дата'],category:['category','категория']};let idx={};for(const [k,v]of Object.entries(aliases))idx[k]=headers.findIndex(x=>v.includes(x));if(idx.name<0||idx.amount<0)throw Error('Нужны колонки name (описание) и amount (сумма). Скачайте шаблон.');if(!rows.length||rows.length>1000)throw Error('Нужно от 1 до 1000 строк');importRows=rows.map((r,i)=>{let n=Number(String(r[idx.amount]||'').replace(/\s/g,'').replace(',','.'));if(!Number.isFinite(n)||n<=0)throw Error('Проверьте сумму в строке '+(i+2));if(!r[idx.name]?.trim())throw Error('Нет описания в строке '+(i+2));return {name:r[idx.name].trim(),amount:n,date:idx.date>=0?r[idx.date]:today(),category:idx.category>=0?r[idx.category]:'Импорт'}});modal('Проверка импорта','<p class="hint">Будут добавлены '+importRows.length+' расходов на '+money(importRows.reduce((s,x)=>s+x.amount,0))+'. Повторный импорт добавит дубликаты.</p><div class="tablewrap"><table><tbody>'+importRows.slice(0,8).map(r=>'<tr><td>'+esc(r.name)+'</td><td>'+money(r.amount)+'</td><td>'+esc(r.date)+'</td></tr>').join('')+'</tbody></table></div><div class="actions"><button class="btn" onclick="confirmImport(this)">Подтвердить импорт</button><button class="btn light" onclick="$(\'modal\').close()">Отмена</button></div>')}catch(e){toast(e.message)}input.value=''}
async function confirmImport(b){b.disabled=true;try{let r=await api('import',{rows:importRows});$('modal').close();await reload();render();toast('Добавлено расходов: '+r.count)}catch(e){toast(e.message);b.disabled=false}}
function csvCell(v){let x=String(v??'');if(/^[=+@-]/.test(x))x="'"+x;return '"'+x.replace(/"/g,'""')+'"'}
function exportRows(rows,name){dl('\uFEFF'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n'),name,'text/csv;charset=utf-8')}
function exportCatalog(){exportRows([['Наименование','Категория','Цена','Себестоимость','Продано','Наличие','Единица','Описание','Синонимы','Тип данных'],...(state.catalog||[]).map(x=>[x.item_name,x.category,x.item_price,x.item_cost,x.units_sold,catalogAvailability[x.details?.availability||'unknown'],x.details?.unit||'',x.details?.description||'',x.details?.aliases||'',x.details?.data_mode==='demo'?'Демонстрация':'Реальные'])],'catalog.csv')}
function exportExpenses(){exportRows([['name','amount','date','category'],...(state.expenses||[]).map(x=>[x.data.name,x.data.amount,x.data.date,x.data.category])],'expenses.csv')}
function openInvoice(){modal('Счёт / коммерческое предложение','<form onsubmit="makeInvoice(event)"><div class="fields">'+select('type','Документ',['Счёт на оплату','Коммерческое предложение'])+field('number','Номер документа','text','AA-'+Date.now().toString().slice(-6),'required')+field('customer','Заказчик','text','','required')+field('seller','Поставщик','text',BOOT.biz,'required')+field('bin','БИН / ИИН поставщика','text','','required pattern="[0-9]{12}" maxlength="12"')+field('iban','IBAN','text','','required')+field('name','Товар / услуга','text','','required')+field('qty','Количество','number','1','min="0.001" step="0.001" required')+field('price','Цена, ₸','number','','min="0.01" step="0.01" required')+field('terms','Условия и НДС','text','Без НДС. Условия уточнить.','required')+'</div><div class="actions"><button class="btn" type="submit">Создать документ</button></div><p class="hint">Это документ для согласования, не фискальный чек и не ЭСФ. Проверьте реквизиты и применимость НДС.</p></form>')}
async function makeInvoice(ev){ev.preventDefault();let d=formData(ev.target),sum=Math.round(Number(d.qty)*Number(d.price)*100)/100;lastTitle=d.type+' № '+d.number;lastResult=lastTitle+'\nДата: '+today()+'\n\nПоставщик: '+d.seller+'\nБИН/ИИН: '+d.bin+'\nIBAN: '+d.iban+'\nЗаказчик: '+d.customer+'\n\n'+d.name+'\nКоличество: '+d.qty+'\nЦена: '+preciseMoney(d.price)+'\nИТОГО: '+preciseMoney(sum)+'\n\nУсловия: '+d.terms+'\n\nДокумент требует проверки и согласования. Не является фискальным чеком.';try{await api('save',{kind:'documents',data:{name:lastTitle,text:lastResult,type:'invoice'}});await reload();$('modal').close();location.hash='documents';render();toast('Документ создан и сохранён')}catch(e){toast(e.message)}}
function toi(){return head(tr('Той-смета','Той сметасы'),'Рассчитайте продукты, столы и бюджет по своим ценам.')+'<div class="grid twocol"><section class="card"><h2>Параметры праздника</h2><form id="toiForm" onsubmit="calculateToi(event)"><div class="fields">'+select('type','Мероприятие',['Той','Ұзату','Құдалық','Семейный праздник'])+field('guests','Гостей','number','100','min="1" max="10000" step="1" required')+field('seats','Мест за столом','number','10','min="1" max="100" step="1" required')+field('meat','Мясо на гостя, кг','number','0.35','min="0" max="5" step="0.01" required')+field('meatprice','Цена мяса за кг, ₸','number','3500','min="0" step="0.01" required')+field('other','Остальное меню на гостя, ₸','number','5000','min="0" step="0.01" required')+field('venue','Зал, ведущий и прочие расходы, ₸','number','300000','min="0" step="0.01" required')+field('reserve','Резерв бюджета, %','number','10','min="0" max="100" step="0.1" required')+'</div><p class="hint">Начальные значения — пример, а не нормы питания или актуальные рыночные цены. Укажите меню и цены вашего поставщика.</p><div class="actions"><button class="btn" type="submit">Рассчитать смету</button></div></form></section><section class="card"><h2>Смета и рассадка</h2><div id="aiResult" class="result" data-empty="Заполните параметры и нажмите «Рассчитать»."></div><div class="actions"><button class="btn light small" onclick="saveResult()">Сохранить смету</button><button class="btn light small" onclick="printResult()">PDF / печать</button></div></section></div>'}
function calculateToi(ev){ev.preventDefault();const d=formData(ev.target),g=Number(d.guests),seats=Number(d.seats),tables=Math.ceil(g/seats),kg=Math.round(g*Number(d.meat)*100)/100,meat=kg*Number(d.meatprice),food=g*Number(d.other),base=meat+food+Number(d.venue),reserve=base*Number(d.reserve)/100;if(!Number.isFinite(base)||base<0){toast('Проверьте суммы');return}lastTitle='Смета: '+d.type;lastResult=d.type+' · '+g+' гостей\n\nМясо: '+kg+' кг × '+money(d.meatprice)+' = '+money(meat)+'\nОстальное меню: '+money(food)+'\nЗал и услуги: '+money(d.venue)+'\nПодытог: '+money(base)+'\nРезерв '+d.reserve+'%: '+money(reserve)+'\n\nИТОГО: '+money(base+reserve)+'\nНа одного гостя: '+money((base+reserve)/g)+'\n\nРассадка: '+tables+' столов по '+seats+' мест.\n'+Array.from({length:tables},(_,i)=>'Стол '+(i+1)+': гости '+(i*seats+1)+'–'+Math.min((i+1)*seats,g)).join('\n')+'\n\nРасчёт по введённым значениям. Согласуйте меню и цены перед закупкой.';$('aiResult').textContent=lastResult}
function taxTool(){return '<section class="card" style="margin-bottom:24px"><h2>Контроль лимита</h2><p>Введите лимит, подтверждённый вашим бухгалтером для вашего режима и периода. Приложение не подставляет устаревшие налоговые пороги.</p><form onsubmit="taxCalc(event)"><div class="fields">'+field('turnover','Оборот за период, ₸','number','','min="0" step="0.01" required')+field('limit','Подтверждённый лимит, ₸','number','','min="0.01" step="0.01" required')+'</div><div class="actions"><button class="btn light" type="submit">Проверить запас</button></div></form><div id="taxResult" class="hint" style="margin-top:14px"></div></section>'}
function taxCalc(ev){ev.preventDefault();const d=formData(ev.target),a=Number(d.turnover),b=Number(d.limit),p=a/b*100;$('taxResult').textContent=p>=100?'Введённый лимит достигнут или превышен на '+money(a-b)+'. Уточните действия с бухгалтером.':'Использовано '+p.toFixed(1)+'% лимита. Остаток '+money(b-a)+'.'+(p>=80?' Приближаетесь к порогу.':'')}
function knowledgeTool(){return '<section class="card" style="margin-bottom:24px"><h2>База знаний</h2><p>Внутренние инструкции доступны ИИ в кабинете. Публичные ответы дополнительно используются Telegram-ботом для клиентов.</p><a class="btn light" href="#knowledge">Открыть базу знаний и импорт Excel</a></section>'}
function knowledgePage(){return '<div class="actions" style="margin-bottom:20px"><button class="btn light" onclick="openSmartImport(\'auto\')">Разобрать произвольный файл с ИИ</button></div>'+head('База знаний и Excel','Загрузите реальные сведения: ассортимент, условия, ответы на вопросы. Не загружайте пароли и персональные данные клиентов.')+'<div class="grid twocol"><section class="card"><h2>Добавить ответ или правило</h2><form onsubmit="submitForm(event,\'save\',\'knowledge\')"><div class="fields">'+field('name','Тема','text','','required maxlength="180"')+textfield('text','Ответ / инструкция','До 4000 символов')+'<div class="field"><label for="knowledgeAudience">Кому доступно</label><select id="knowledgeAudience" name="audience"><option value="internal">Только команде</option><option value="public">Клиентам Telegram и команде</option></select></div></div><div class="actions"><button type="submit" class="btn">Сохранить</button></div></form></section><section class="card"><h2>Импорт Excel / CSV</h2><p>До 500 строк, файл до 2 МБ. Колонки: name (тема), text (ответ), audience (internal или public). Пустой доступ означает «только команде». Перед импортом покажем строки для проверки. Одинаковые записи пропускаются.</p><div class="actions"><button class="btn light" onclick="downloadKnowledgeTemplate()">Шаблон Excel</button><label class="btn" for="knowledgeFile">Выбрать файл</label><input id="knowledgeFile" type="file" accept=".xlsx,.xls,.csv" hidden onchange="previewKnowledge(this)"></div></section></div><section class="card" style="margin-top:20px"><h2>Проверить ответ клиентского бота</h2><p>Использует только каталог и публичные ответы. Сообщение в Telegram не отправляется.</p><form onsubmit="previewBot(event)"><div class="field"><label for="botQuestion">Вопрос клиента</label><input id="botQuestion" name="question" required maxlength="2000"></div><div class="actions"><button class="btn" type="submit">Проверить ответ</button></div></form><div id="botAnswer" class="result"></div></section><section class="card" style="margin-top:20px"><h2>Сохранённые сведения · '+state.knowledge.length+'</h2>'+state.knowledge.map(x=>'<div class="row"><div><b>'+esc(x.data.name)+'</b><small>'+esc(x.data.text)+'</small><span class="badge">'+(x.data.audience==='public'?'Для клиентов Telegram':'Только команде')+'</span></div><button class="btn light small" onclick="archiveRecord('+x.id+')">В архив</button></div>').join('')+'</section>'}
async function previewBot(ev){ev.preventDefault();let b=ev.target.querySelector('button'),out=$('botAnswer');b.disabled=true;out.textContent='Готовим ответ…';try{let r=await api('ai',{module:'bot_preview',prompt:ev.target.question.value,lang});out.textContent=r.text;await reload()}catch(e){out.textContent=e.message}finally{b.disabled=false}}
let knowledgeRows=[];
async function downloadKnowledgeTemplate(){const XLSX=await loadSheetLibrary();const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet([['name','text','audience']]),'База знаний');XLSX.writeFile(wb,'business-knowledge-template.xlsx')}
async function previewKnowledge(input){try{const f=input.files[0];if(!f)return;if(f.size>2000000)throw Error('Файл до 2 МБ');const rows=await readImportRows(f),h=rows.shift().map(x=>String(x).trim().toLowerCase()),find=a=>h.findIndex(x=>a.includes(x)),n=find(['name','тема','вопрос','название']),t=find(['text','ответ','инструкция','описание']),a=find(['audience','доступ']);if(n<0||t<0)throw Error('Нужны колонки name и text. Скачайте шаблон.');if(!rows.length||rows.length>500)throw Error('Нужно от 1 до 500 строк');knowledgeRows=rows.map((r,i)=>{const d={name:String(r[n]||'').trim(),text:String(r[t]||'').trim(),audience:a<0||!String(r[a]||'').trim()?'internal':String(r[a]).trim().toLowerCase()};if(!d.name||!d.text||d.name.length>180||d.text.length>4000||!['internal','public'].includes(d.audience))throw Error('Проверьте строку '+(i+2)+': тема, текст и доступ internal/public');return d});modal('Проверка базы знаний','<p>Строк: '+knowledgeRows.length+'. Для клиентов Telegram: '+knowledgeRows.filter(x=>x.audience==='public').length+'. Публичные ответы будут переданы Gemini при вопросах клиентов. Проверьте, что в них нет внутренних данных.</p><div class="tablewrap"><table>'+knowledgeRows.slice(0,10).map(r=>'<tr><td>'+esc(r.name)+'</td><td class="wrap">'+esc(r.text)+'</td><td>'+esc(r.audience)+'</td></tr>').join('')+'</table></div><div class="actions"><button class="btn" onclick="confirmKnowledge(this)">Импортировать в базу</button><button class="btn light" onclick="$(\'modal\').close()">Отмена</button></div>')}catch(e){toast(e.message)}finally{input.value=''}}
async function confirmKnowledge(b){b.disabled=true;try{const r=await api('import_knowledge',{rows:knowledgeRows});$('modal').close();await reload();render();toast('Добавлено: '+r.count+'; повторов пропущено: '+r.skipped)}catch(e){toast(e.message);b.disabled=false}}

function b2b(){const rows=state.offers||[];return head('B2B Jambyl Coop','Планируйте совместные закупки, предложения фермеров и бартер.')+'<div class="notice">Сначала сохраните свой черновик, затем нажмите «Публикация» и проверьте открытые поля. Публикации видны другим предпринимателям в приложении. Заявка выражает интерес; оплату и договорённости стороны согласуют напрямую.</div><div class="grid twocol"><section class="card"><h2>Новое предложение</h2><form onsubmit="submitForm(event,\'save\',\'offers\')"><div class="fields">'+select('type','Тип',['Совместная закупка','Предложение поставщика','Бартер услуг'])+field('name','Товар / услуга','text','','required')+field('quantity','Количество / объём','text','','required')+field('price','Целевая цена / условия','text','','required')+field('contact','Контакт партнёра','text')+field('location','Город / район','text',BOOT.location)+textfield('note','Описание и условия')+'</div><div class="actions"><button class="btn" type="submit">Сохранить предложение</button></div></form><hr style="border:0;border-top:1px solid var(--line);margin:24px 0"><h3>Выгода оптовой закупки</h3><form onsubmit="coopCalc(event)"><div class="fields">'+field('retail','Обычная цена за единицу, ₸','number','','min="0" step="0.01" required')+field('wholesale','Оптовая цена, ₸','number','','min="0" step="0.01" required')+field('qty','Общий объём','number','','min="0.001" step="0.001" required')+field('delivery','Доставка и сборы, ₸','number','0','min="0" step="0.01" required')+'</div><div class="actions"><button class="btn light" type="submit">Рассчитать выгоду</button></div><p id="coopResult" class="hint"></p></form></section><section class="card"><h2>Мои предложения</h2>'+(rows.length?rows.map(r=>'<div class="row"><div><span class="badge">'+esc(r.data.type)+'</span><h3 style="margin:10px 0 5px">'+esc(r.data.name)+'</h3><small>'+esc(r.data.quantity)+' · '+esc(r.data.price)+'<br>'+esc(r.data.location)+' · '+esc(r.data.contact)+'</small><p>'+esc(r.data.note)+'</p></div><div><button class="btn light small" onclick="offerDocument('+r.id+')">Документ</button><button class="btn light small" onclick="publishOfferModal('+r.id+')">Публикация</button><button class="btn light small" onclick="archiveRecord('+r.id+')">В архив</button></div></div>').join(''):empty('Сохраните первое предложение.'))+'</section></div>'}
function coopCalc(ev){ev.preventDefault();let d=formData(ev.target),normal=Number(d.retail)*Number(d.qty),cost=Number(d.wholesale)*Number(d.qty)+Number(d.delivery);$('coopResult').textContent='Обычная закупка: '+money(normal)+'. Совместная: '+money(cost)+'. Разница: '+money(normal-cost)+(cost>normal?' — совместная закупка дороже.':'.')}
function offerDocument(id){const r=state.offers.find(x=>Number(x.id)===id);lastTitle=r.data.type+': '+r.data.name;lastResult=Object.entries(r.data).map(([k,v])=>({type:'Тип',name:'Наименование',quantity:'Объём',price:'Условия',contact:'Контакт',location:'Локация',note:'Описание'}[k]||k)+': '+v).join('\n');printResult()}
function documents(){let rows=state.documents||[];return head(tr('Мои документы','Менің құжаттарым'),'Все сохранённые результаты в вашем рабочем пространстве.','<button class="btn" onclick="openInvoice()">＋ Счёт / КП</button>')+'<section class="card">'+(rows.length?rows.map(r=>'<div class="row"><div><b>'+esc(r.data.name)+'</b><small>'+esc(r.created_at)+' · '+esc(r.data.type||'документ')+'</small></div><div class="actions" style="margin:0"><button class="btn light small" onclick="viewDocument('+r.id+')">Открыть</button><button class="btn light small" onclick="downloadDocument('+r.id+')">TXT</button><button class="btn light small" onclick="documentPdf('+r.id+')">PDF</button><button class="btn light small" onclick="archiveRecord('+r.id+')">В архив</button></div></div>').join(''):empty('Сохраните смету, создайте счёт или документ с помощью ИИ.'))+'</section>'}
function viewDocument(id){let x=state.documents.find(x=>Number(x.id)===id);lastResult=x.data.text;lastTitle=x.data.name;modal(lastTitle,'<div class="result">'+esc(lastResult)+'</div><div class="actions"><button class="btn light" onclick="copyResult()">Копировать</button><button class="btn" onclick="documentPdf('+id+')">PDF / печать</button></div>')}
function downloadDocument(id){let x=state.documents.find(x=>Number(x.id)===id);dl(x.data.name+'\n\n'+x.data.text,'aulieata-document-'+id+'.txt')}
function documentPdf(id){let x=state.documents.find(x=>Number(x.id)===id);lastResult=x.data.text;lastTitle=x.data.name;printResult()}
function settings(){return businessSetupSummary()+profileTool()+imageAiSettings()+tiktokConnectionTool()+instagramConnectionTool()+telegramConnectionTool()+ head(tr('Подключения и возможности','Қосылымдар мен мүмкіндіктер'),'Понятный статус каждого сервиса и необходимые шаги.')+'<div class="grid twocol"><section class="card"><h2>Рабочее пространство</h2><div class="row"><div><b>'+esc(BOOT.biz)+'</b><small>'+esc(BOOT.location)+'</small></div><span class="badge">MySQL</span></div><ul class="checklist"><li>✓ Каталог, клиенты, записи, документы и расходы сохраняются на сервере для вашего аккаунта.</li><li>✓ Счета, КП и сметы создаются без обращения к ИИ.</li><li>✓ PDF сохраняется через системное окно печати → «Сохранить как PDF».</li><li>✓ Импорт расходов: CSV, XLSX и XLS, включая экспорт из Excel и 1С.</li><li>△ Казахский язык: навигация и выбор языка ИИ; часть рабочих форм пока на русском.</li><li>✓ Облачная озвучка QazKazVoice (до 1200 символов). Голосовой ввод в браузере зависит от поддержки микрофона и языка.</li></ul></section><section class="card"><h2>Внешние сервисы</h2>'+[['Google Gemini','Серверный запрос и резервная модель при перегрузке; доступность зависит от квот Google','Настроен'],['Google Search','Поиск программ поддержки с источниками; нужна доступная квота поиска в проекте Google','По тарифу Google'],['WhatsApp Business','Нужны Business Account, номер, токен и webhook','Не подключён'],['Telegram Bot',(state.connection?state.connection.active:!!BOOT.telegram_username)?'@'+(state.connection?.username||BOOT.telegram_username)+' · текст и голосовые сообщения':'Нужны токен BotFather и webhook',BOOT.telegram_username?'Подключён':'Не подключён'],['Google Calendar','Нужно OAuth-подключение; сейчас доступен .ics','Не подключён'],['2GIS / Google Maps','Нужны доступ API, ID организации и разрешения','Не подключён'],['Kaspi Pay / 1С','CSV-импорт доступен; автоматическая синхронизация отдельно','Не подключён'],['Enbek.kz','Черновики документов доступны; подача вручную','Не подключён']].map(x=>'<div class="row"><div><b>'+x[0]+'</b><small>'+x[1]+'</small></div><span class="'+(x[2]==='Подключён'||x[2]==='Настроен'?'badge':'badge pending')+'">'+x[2]+'</span></div>').join('')+'</section></div>'}
function render(){const key=location.hash.slice(1)||'dashboard';current=visibleModules().some(x=>x[0]===key)?key:'dashboard';renderNav();$('crumb').textContent=visibleModules().find(x=>x[0]===current)[lang==='kk'?3:2];$('sidebar').classList.remove('open');imageData='';lastResult='';lastTitle='';const pages={marketing:socialStudioPage,operations:operationsPage,dashboard,catalog,clients,inbox,bookings,toi,b2b,documents,archives,settings,knowledge:knowledgePage,agent:agentPage,automations:automationsPage,opportunities:opportunitiesPage,sector:sectorPage};$('content').innerHTML=pages[current]?pages[current]():aiWorkspace(current);if(current==='agent'&&$('agentPrompt')){let q=sessionStorage.getItem('aulieata.agentPrompt');if(q){$('agentPrompt').value=q;sessionStorage.removeItem('aulieata.agentPrompt')}}if(current==='settings'){if($('f_description'))$('f_description').value=(state.profile||BOOT.profile).description||'';if($('f_rules'))$('f_rules').value=(state.profile||BOOT.profile).rules||'';}if($('f_language'))$('f_language').value=lang==='kk'?'Қазақша':'Русский';if(current==='sales'){let q=sessionStorage.getItem('aulieata.prompt');if(q){$('f_prompt').value=q;sessionStorage.removeItem('aulieata.prompt')}}if(current==='b2b')$('content').insertAdjacentHTML('beforeend',marketView());window.scrollTo(0,0);socialMount();serviceMount();imageAiMount()}
$('bizName').textContent=BOOT.biz;$('bizLocation').textContent=BOOT.location;$('avatar').textContent=BOOT.biz.charAt(0).toUpperCase();window.addEventListener('hashchange',render);document.addEventListener('keydown',e=>{if(e.key==='Escape')$('sidebar').classList.remove('open')});
reload().then(render).catch(e=>{$('content').innerHTML='<div class="error">'+esc(e.message)+'</div><button class="btn" onclick="location.reload()">Повторить</button>'});

function editCatalog(id){let x=state.catalog.find(x=>Number(x.id)===id);openCatalog();let f=document.querySelector('#modalBody form');f.setAttribute('onsubmit',"submitForm(event,'edit_catalog')");let input=document.createElement('input');input.type='hidden';input.name='id';input.value=id;f.append(input);for(const k of ['item_name','category','item_price','item_cost','units_sold'])f.elements[k].value=x[k];for(const k of ['availability','unit','description','aliases','data_mode'])f.elements[k].value=x.details?.[k]??(k==='availability'?'unknown':k==='data_mode'?'live':'');document.querySelector('#modalBody h2').textContent='Изменить позицию'}

function archives(){const rows=state.archives||[];return head(tr('Архив','Мұрағат'),'Записи сохранены и могут быть восстановлены.')+'<section class="card">'+(rows.length?rows.map(r=>'<div class="row"><div><b>'+esc(r.data.name)+'</b><small>'+esc(r.kind)+' · '+esc(r.created_at)+'</small></div><button class="btn light small" onclick="'+(r.kind==='catalog'?'restoreCatalog':'restoreRecord')+'('+r.id+')">Восстановить</button></div>').join(''):empty('В архиве пока нет записей.'))+'</section>'}
async function restoreRecord(id){try{await api('restore',{id});await reload();render();toast('Запись восстановлена')}catch(e){toast(e.message)}}
let sheetLibrary;
async function loadSheetLibrary(){if(window.XLSX)return window.XLSX;if(!sheetLibrary)sheetLibrary=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://cdn.sheetjs.com/xlsx-0.20.3/package/dist/xlsx.full.min.js';s.onload=()=>resolve(window.XLSX);s.onerror=()=>{sheetLibrary=null;reject(Error('Не удалось загрузить обработчик Excel. Используйте CSV или повторите позже.'))};document.head.append(s)});return sheetLibrary}
async function readImportRows(file){if(/\.xlsx?$/i.test(file.name)){const XLSX=await loadSheetLibrary();const book=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:true,sheetRows:1002});if(!book.SheetNames.length)throw Error('В книге нет листов');const rows=XLSX.utils.sheet_to_json(book.Sheets[book.SheetNames[0]],{header:1,raw:false,defval:''});return rows.filter(r=>r.some(v=>String(v).trim())).map(r=>r.map(String))}return parseCSV(await file.text())}


function inbox(){const rows=state.telegram_messages||[];return head('Telegram · входящие','Обращения клиентов и ответы QazKazVoice.', '<button class="btn light" onclick="refreshInbox()">Обновить</button>')+(BOOT.telegram_username?'<div class="notice">Бот <a href="https://t.me/'+esc(state.connection?.username||BOOT.telegram_username)+'" target="_blank" rel="noopener">@'+esc(BOOT.telegram_username)+'</a> подключён. Режим обслуживания выбирается в Операционном центре → Настройка. Бот использует каталог этого бизнеса и публичную базу знаний. Заказ или запись создаются после подтверждения клиента, если владелец включил приём.</div>':'<div class="notice">Telegram-бот для этого аккаунта ещё не подключён.</div>')+'<section class="card">'+(rows.length?rows.map(r=>'<article style="padding:18px 0;border-bottom:1px solid var(--line)"><div style="display:flex;justify-content:space-between;gap:12px"><b>Чат '+esc(r.data.chat_id)+'</b><span class="badge">'+esc(r.data.type||'text')+' · '+(r.data.status==='processing'?'Обрабатывается':r.data.status==='failed'?'Ошибка обработки':r.data.status==='needs_text'?'Ожидается текст':'Ответ отправлен')+(r.data.audio_reply==='sent'?' · Аудио отправлено':r.data.audio_reply==='failed'?' · Аудио недоступно':'')+'</span></div><p class="hint">'+esc(r.created_at)+'</p><div class="result">'+esc(r.data.text)+'</div><div style="margin-top:14px;padding:16px;background:var(--soft);border-radius:10px"><b>✳ QazKazVoice</b><div class="result" style="margin-top:8px">'+esc(r.data.reply)+'</div></div></article>').join(''):empty('Входящих сообщений пока нет. Напишите боту в Telegram, чтобы проверить канал.'))+'</section>'}
async function refreshInbox(){try{await reload();render();toast('Входящие обновлены')}catch(e){toast(e.message)}}


async function archiveCatalog(id){try{await api('archive_catalog',{id});await reload();render();toast('Позиция в архиве. Её можно восстановить.')}catch(e){toast(e.message)}}
async function restoreCatalog(id){try{await api('restore_catalog',{id});await reload();render();toast('Позиция восстановлена')}catch(e){toast(e.message)}}


function marketView(){const rows=state.market||[],members=state.coop_members||[];return '<div class="sectiontitle"><h2>Маркетплейс предпринимателей</h2><button class="btn light small" onclick="refreshInbox()">Обновить</button></div><input class="search" aria-label="Поиск предложений" placeholder="Товар, район, поставщик…" oninput="document.querySelectorAll(\'.market-card\').forEach(e=>e.hidden=!e.textContent.toLowerCase().includes(this.value.toLowerCase()))"><div class="grid modulegrid" style="margin-top:20px">'+(rows.length?rows.map(r=>'<article class="card market-card"><span class="badge">'+esc(r.data.type)+'</span><h3 style="margin-top:15px">'+esc(r.data.name)+'</h3><p>'+esc(r.data.company)+' · '+esc(r.data.location)+'</p><p>'+esc(r.data.price)+'<br>Цель: '+Number(r.target_quantity)+' '+esc(r.data.unit)+'<br>Заявлено: '+Number(r.joined_quantity)+' · Участников: '+Number(r.participants)+'</p><div class="bar"><span style="width:'+Math.min(100,Number(r.joined_quantity)/Number(r.target_quantity)*100)+'%"></span></div><p>'+esc(r.data.note)+'</p><p>Контакт: '+esc(r.data.contact)+'</p><div class="actions">'+(r.own?'<button class="btn light small" onclick="showPledges('+r.id+')">Заявки</button><button class="btn light small" onclick="withdrawOffer('+r.id+')">Снять</button>':'<button class="btn small" onclick="joinOfferModal('+r.id+')">Подать заявку</button>')+'</div></article>').join(''):empty('Публикаций пока нет. Можно стать первым поставщиком или организатором закупки.'))+'</div>'+ (members.length?'<div class="sectiontitle"><h2>Мои заявки и заявки к моим предложениям</h2></div><div class="card">'+members.map(r=>'<div class="row"><div><b>'+esc(JSON.parse(r.body).name)+'</b><small>'+esc(r.name)+' · '+Number(r.quantity)+' · '+esc(r.contact)+'</small></div>'+(r.own?'<button class="btn light small" onclick="cancelPledge('+r.id+')">Отозвать мою заявку</button>':'<span class="badge">Участник закупки</span>')+'</div>').join('')+'</div>':'')}
function publishOfferModal(id){const r=state.offers.find(x=>Number(x.id)===id),pub=(state.my_publications||[]).find(x=>Number(x.record_id)===id);modal('Публикация для предпринимателей','<p class="notice">Эти поля будут видны всем пользователям B2B-площадки. Публикуйте контакт, который разрешено использовать для деловой связи.</p><form onsubmit="publishOffer(event,'+id+')"><div class="fields">'+field('name','Наименование','text',r.data.name,'required')+field('type','Тип предложения','text',r.data.type,'required')+field('target_quantity','Целевой объём / доступное количество','number','','min="0.001" step="0.001" required')+field('unit','Единица измерения','text','кг / шт. / услуга','required')+field('price','Цена и условия','text',r.data.price,'required')+field('contact','Открытый контакт для связи','text',r.data.contact||'','required')+field('location','Район / город','text',r.data.location||BOOT.location,'required')+textfield('note','Описание', '',r.data.note||'')+'</div><div class="actions"><button class="btn" type="submit">Опубликовать открытые поля</button>'+(pub&&Number(pub.active)?'<button type="button" class="btn light" onclick="withdrawOffer('+pub.id+')">Снять публикацию</button>':'')+'</div></form>')}
async function publishOffer(ev,id){ev.preventDefault();let b=ev.target.querySelector('[type=submit]');b.disabled=true;try{await api('publish_offer',{record_id:id,data:formData(ev.target)});$('modal').close();await reload();render();toast('Предложение опубликовано')}catch(e){toast(e.message);b.disabled=false}}
async function withdrawOffer(id){try{await api('withdraw_offer',{id});$('modal').close();await reload();render();toast('Публикация снята')}catch(e){toast(e.message)}}
function joinOfferModal(id){let x=state.market.find(x=>Number(x.id)===id);modal('Заявка: '+x.data.name,'<p class="notice">Имя, контакт и объём увидит организатор «'+esc(x.data.company)+'». Это заявка без оплаты; условия согласуются напрямую.</p><form onsubmit="joinOffer(event,'+id+')"><div class="fields">'+field('name','Ваше имя / бизнес','text',BOOT.biz,'required')+field('contact','Контакт для организатора','text','','required')+field('quantity','Объём заявки, '+x.data.unit,'number','','min="0.001" step="0.001" max="'+(Number(x.target_quantity)-Number(x.joined_quantity))+'" required')+'</div><div class="actions"><button class="btn" type="submit">Передать заявку организатору</button></div></form>')}
async function joinOffer(ev,id){ev.preventDefault();try{await api('join_offer',{id,...formData(ev.target)});$('modal').close();await reload();render();toast('Заявка передана')}catch(e){toast(e.message)}}
function showPledges(id){let rows=(state.coop_members||[]).filter(x=>Number(x.market_id)===id);modal('Заявки участников',rows.length?rows.map(r=>'<div class="row"><div><b>'+esc(r.name)+'</b><small>'+esc(r.contact)+' · '+Number(r.quantity)+'</small></div></div>').join(''):empty('Заявок пока нет.'))}
async function cancelPledge(id){try{await api('cancel_pledge',{id});await reload();render();toast('Ваша заявка отозвана')}catch(e){toast(e.message)}}


function sourceLinks(r){let sources=(r.sources||[]).filter(x=>/^https?:\/\//i.test(x.url));let html=sources.length?'<div class="sectiontitle"><h3>Источники поиска</h3></div>'+sources.map((x,i)=>'<p><a href="'+esc(x.url)+'" target="_blank" rel="noopener noreferrer">'+(i+1)+'. '+esc(x.title)+' ↗</a></p>').join(''):'';if(r.search_widget)html+='<iframe title="Подсказки Google Search" sandbox="allow-popups allow-popups-to-escape-sandbox" style="width:100%;height:150px;border:0" srcdoc="'+esc(r.search_widget)+'"></iframe>';return html}

function telegramConnectionTool(){let c=state.connection,connected=c?c.active:!!BOOT.telegram_username,u=c?.username||BOOT.telegram_username;return '<section id="telegramConnection" class="card" style="margin-bottom:24px"><h2>Ваш Telegram-бот</h2><p>У каждого аккаунта собственный бот, каталог и история. Создайте бота в BotFather и вставьте его токен. Подключение заменит прежний обработчик этого бота. Токен хранится в зашифрованном виде и не показывается после сохранения.</p>'+(connected?'<p><span class="badge">Подключён</span> <a target="_blank" rel="noopener" href="https://t.me/'+esc(u)+'">@'+esc(u)+'</a></p>':'<p class="hint">Бот пока не подключён.</p>')+'<form onsubmit="connectTelegram(event)"><div class="field"><label for="telegramToken">Токен из BotFather</label><input id="telegramToken" name="token" type="password" autocomplete="off" placeholder="Вставьте токен" required></div><div class="actions"><button type="submit" class="btn">'+(connected?'Проверить / переподключить':'Подключить бота')+'</button>'+(c?.active?'<button type="button" class="btn light" onclick="disconnectTelegram(this)">Отключить</button>':'')+'</div></form><p class="hint">После «Старт» — приветствие и свободный диалог. Клиент пишет или говорит запрос, без выбора команд.</p></section>'}
async function connectTelegram(ev){ev.preventDefault();let b=ev.target.querySelector('button');b.disabled=true;try{let r=await api('telegram_connect',{token:ev.target.token.value});ev.target.token.value='';await reload();render();toast('Бот @'+r.username+' подключён')}catch(e){toast(e.message)}finally{b.disabled=false}}
async function disconnectTelegram(b){b.disabled=true;try{await api('telegram_disconnect');await reload();render();toast('Бот отключён')}catch(e){toast(e.message);b.disabled=false}}
const importFields={stock_batches:{name:'Название',quantity:'Остаток',unit:'Единица',price:'Цена',cost:'Себестоимость',expires_on:'Годен до YYYY-MM-DD',received_on:'Поступление YYYY-MM-DD',batch:'Партия',min_stock:'Минимум',condition:'Состояние'},business_capacity:{name:'Ресурс',quantity:'Свободно',unit:'Единица',price:'Цена',cost:'Себестоимость',date:'Дата YYYY-MM-DD',note:'Примечание'},catalog:{name:'Название',price:'Цена, ₸',sku:'Артикул / SKU',availability:'Наличие',unit:'Единица',description:'Описание',aliases:'Синонимы',cost:'Себестоимость',quantity:'Продано, шт.',category:'Категория',data_mode:'live / demo'},clients:{name:'Имя',phone:'Телефон',email:'Email',note:'Заметка'},expenses:{name:'Описание',amount:'Сумма, ₸',date:'Дата',category:'Категория'},knowledge:{name:'Тема',text:'Ответ / инструкция',audience:'Доступ'}};
let smartDraft=null,smartSource=[];
function openSmartImport(target='auto'){smartSource=[];modal('Импорт с разбором ИИ','<p class="hint">Excel, CSV или TXT до 2 МБ. До 500 строк и 40 колонок. ИИ определит колонки или выделит позиции из текста; вы сможете исправить результат перед сохранением. Содержимое файла будет передано Google Gemini. Существующие позиции не перезаписываются.</p><div class="fields"><div class="field"><label for="smartTarget">Куда импортировать</label><select id="smartTarget">'+Object.entries({auto:'Определить автоматически',stock_batches:'Партии и физические остатки',business_capacity:'Свободные места / часы',catalog:'Каталог / меню',clients:'Клиенты',expenses:'Расходы',knowledge:'База знаний'}).map(([k,v])=>'<option value="'+k+'" '+(k===target?'selected':'')+'>'+v+'</option>').join('')+'</select></div><div class="field"><label for="smartFile">Файл</label><input id="smartFile" type="file" accept=".xlsx,.xls,.csv,.txt" onchange="readSmartFile(this)"></div><div class="field span2"><label for="smartPaste">Или вставьте таблицу / текст</label><textarea id="smartPaste" placeholder="Название&#9;Цена&#10;Капучино&#9;1200"></textarea></div></div><div class="actions"><button class="btn" id="smartAnalyze" onclick="analyzeSmart(this)">Разобрать с ИИ</button></div><div id="smartError" role="alert"></div>')}
async function readSmartFile(input){try{const f=input.files[0];if(!f)return;if(f.size>2000000)throw Error('Файл до 2 МБ');smartSource=await readImportRows(f);$('smartPaste').value=smartSource.map(r=>r.join('\t')).join('\n');toast('Файл прочитан: '+smartSource.length+' строк')}catch(e){toast(e.message)}}
async function analyzeSmart(b){b.disabled=true;try{let raw=$('smartPaste').value;if(!raw.trim())throw Error('Выберите файл или вставьте таблицу');let rows=smartSource.length&&raw===smartSource.map(r=>r.join('\t')).join('\n')?smartSource:raw.includes('\t')?raw.split(/\r?\n/).filter(x=>x.trim()).map(x=>x.split('\t')):parseCSV(raw);let r=await api('analyze_import',{...(rows.every(x=>x.length<=1)?{free_text:raw}:{rows}),target:$('smartTarget').value});smartDraft=r;showSmartPreview()}catch(e){$('smartError').className='error';$('smartError').textContent=e.message;b.disabled=false}}
function showSmartPreview(){const d=smartDraft,f=importFields[d.target];modal('Проверьте строки перед импортом','<p>'+esc(d.explanation||'')+'</p>'+opsImportOptions(d.target)+'<p class="hint">Строк: '+d.rows.length+'. Исправьте выделенные ошибки или снимите выбор строки. Совпадения определяются по артикулу, а при его отсутствии — по названию. Пустое наличие сохраняет прежнее значение; для новых позиций оно требует уточнения. Количество — продажи, не складской остаток. В базе знаний доступ по умолчанию внутренний.</p><div class="tablewrap" style="max-height:50vh"><table><thead><tr><th>Выбрать</th><th>Строка</th>'+Object.values(f).map(v=>'<th>'+v+'</th>').join('')+'</tr></thead><tbody>'+d.rows.map((r,i)=>'<tr><td><input aria-label="Импортировать строку '+r.source_row+'" type="checkbox" id="sr_pick_'+i+'" checked></td><td>'+r.source_row+(r.error?'<small style="display:block;color:#ad3e30;white-space:normal">'+esc(r.error)+'</small>':'')+'</td>'+Object.entries(f).map(([k,v])=>'<td>'+(k==='condition'?'<select id="sr_'+i+'_'+k+'"><option value="blocked">Требует проверки</option><option value="safe">Подтверждаю пригодность и хранение</option></select>':k==='audience'?'<select id="sr_'+i+'_'+k+'"><option value="internal">Только команде</option><option value="public">Клиентам Telegram</option></select>':'<input aria-label="'+v+' строка '+r.source_row+'" style="min-width:130px;width:100%;padding:8px;border:1px solid var(--line);border-radius:6px" id="sr_'+i+'_'+k+'" value="'+esc(r.data[k]??'')+'">')+'</td>').join('')+'</tr>').join('')+'</tbody></table></div><p class="hint">Публичные знания будут доступны клиентскому боту. Проверьте, что там нет внутренних сведений.</p><div class="actions"><button class="btn" onclick="opsReviewImportFromSmart(this)">Посмотреть изменения</button><button class="btn light" onclick="$(\'modal\').close()">Отмена</button></div><div id="smartCommitError" role="alert"></div>');$('modal').style.width='1100px'}
async function commitSmart(b){b.disabled=true;try{let rows=smartDraft.rows.flatMap((r,i)=>$('sr_pick_'+i).checked?[Object.fromEntries(Object.keys(importFields[smartDraft.target]).map(k=>[k,$('sr_'+i+'_'+k).value]))]:[]);let res=await api('commit_smart_import',{draft_id:smartDraft.draft_id,rows});$('modal').close();await reload();render();toast('Добавлено: '+res.count+'. Повторов пропущено: '+res.skipped)}catch(e){$('smartCommitError').className='error';$('smartCommitError').textContent=e.message;b.disabled=false}}
const kindNames={catalog:'Позиция каталога',clients:'Клиент',knowledge:'Внутренняя инструкция',documents:'Документ',tasks:'Задача'};
let agentPlan=null;
function legacyAgentPage(){return head('ИИ-агент вашего бизнеса','Анализирует данные, готовит план и выполняет выбранные вами изменения.')+'<div class="grid twocol"><section class="card assistant"><h2>Что нужно сделать?</h2><p>Например: «Проанализируй меню и создай три задачи для увеличения продаж» или «Добавь капучино за 1200 тенге».</p><form onsubmit="askAgent(event)"><div class="field"><label for="agentPrompt">Задача</label><textarea id="agentPrompt" name="prompt" required maxlength="5000" placeholder="Опишите результат, который хотите получить…"></textarea></div><div class="actions"><button type="submit" class="btn lime">✳ Подготовить план</button><button type="button" class="btn light" onclick="openSmartImport()">Импортировать данные</button></div></form><p class="hint" style="color:#b5c8bc">ИИ получает профиль, каталог и базу знаний только вашего аккаунта. Изменения применяются после проверки. Внешние сообщения и платежи агент не выполняет.</p></section><section class="card"><h2>План и результат</h2><div id="agentOutput" class="result">Опишите задачу, чтобы получить план.</div><div id="agentActions"></div></section></div><section class="card" style="margin-top:20px"><h2>Задачи команды</h2>'+(state.tasks.length?state.tasks.map(t=>'<div class="row"><div><b>'+esc(t.data.name)+'</b><small>'+esc(t.data.text)+'</small><span class="badge">'+esc(t.data.status)+'</span></div>'+(t.data.status!=='Выполнена'?'<button class="btn light small" onclick="doneTask('+t.id+')">Выполнено</button>':'')+'</div>').join(''):empty('Задачи появятся после подтверждения плана агента.'))+'</section><section class="card" style="margin-top:20px"><h2>Последние планы</h2>'+(state.agent_plans||[]).slice(0,10).map(p=>'<div class="row"><div><b>'+esc(p.data.name)+'</b><small>'+esc(p.data.summary?.slice(0,200))+'</small></div><span class="badge">'+(p.data.consumed?'Применён':'Подготовлен')+'</span></div>').join('')+'</section>'}
async function askAgent(ev){ev.preventDefault();let b=ev.target.querySelector('button'),out=$('agentOutput'),acts=$('agentActions');b.disabled=true;out.textContent='Изучаю данные и готовлю план…';acts.innerHTML='';try{agentPlan=await api('agent_plan',{prompt:ev.target.prompt.value});if(!out.isConnected)return;out.textContent='План подготовлен. Изменения ещё не сохранены.\n\n'+agentPlan.summary;acts.innerHTML=agentPlan.actions.map((a,i)=>'<div class="row"><label><input type="checkbox" id="agentCheck_'+i+'" checked> '+esc(kindNames[a.kind])+' · <b>'+esc(a.data.name)+'</b><small>'+esc(JSON.stringify(a.data))+'</small></label></div>').join('')+(agentPlan.actions.length?'<div class="actions"><button class="btn" onclick="applyAgent(this)">Выполнить выбранные действия</button></div>':'');await reload()}catch(e){out.textContent=e.message}finally{b.disabled=false}}
async function applyAgent(b){b.disabled=true;try{let selected=agentPlan.actions.map((x,i)=>i).filter(i=>$('agentCheck_'+i).checked),r=await api('agent_apply',{id:agentPlan.id,selected});await reload();render();toast('Выполнено действий: '+r.count)}catch(e){toast(e.message);b.disabled=false}}
async function doneTask(id){try{await api('task_done',{id});await reload();render()}catch(e){toast(e.message)}}
const jobNames={promotion_auto:['ИИ-идеи акций','Ежедневно готовит черновики по ресурсам с маржой от 20%. Использует квоту Gemini. Публикация только после проверки.'],opportunity_check:['Риски и возможности','Сроки партий, минимальные остатки и свободные ресурсы.'],daily_digest:['Ежедневная сводка','Записи на сегодня и количество обращений.'],catalog_audit:['Проверка каталога','Позиции с ценой не выше себестоимости.'],inbox_followup:['Контроль обращений','Находит сообщения с ошибкой или незавершённой обработкой.']};
function automationsPage(){return (opsState.role==='owner'?socialPlanPanel():'')+head('Автоматизации','Повторяющиеся проверки бизнеса с журналом результатов.')+'<div class="notice">'+esc(socialWorkerStatus())+' Расписание указано по Казахстану, UTC+5. Результаты сохраняются здесь; автоматических рассылок клиентам нет.</div><div class="grid modulegrid">'+Object.entries(jobNames).map(([key,v])=>{let j=state.jobs.find(x=>x.task===key);return '<section class="card"><h2>'+v[0]+'</h2><p>'+v[1]+'</p><form onsubmit="saveAutomation(event,\''+key+'\')"><div class="field"><label for="hour_'+key+'">Ежедневно в</label><select name="hour" id="hour_'+key+'">'+Array.from({length:24},(_,i)=>'<option value="'+i+'" '+(i===Number(j?.hour_local??9)?'selected':'')+'>'+String(i).padStart(2,'0')+':00</option>').join('')+'</select></div><p><label><input type="checkbox" name="enabled" '+(j?.enabled==1?'checked':'')+'> Включить расписание</label></p><div class="actions"><button class="btn small" type="submit">Сохранить</button>'+(j?'<button type="button" class="btn light small" onclick="runAutomation('+j.id+',this)">Проверить сейчас</button>':'')+'</div></form>'+(j?'<p class="hint">Следующий запуск: '+esc(j.next_run)+'<br>Последний результат: '+esc(({waiting:'Ожидает запуска',done:'Выполнено',failed:'Ошибка'})[j.last_status]||j.last_status)+'</p>':'')+'</section>'}).join('')+'</div><section class="card" style="margin-top:24px"><h2>Журнал автоматизаций</h2>'+(state.automation_logs.length?state.automation_logs.map(r=>'<div class="row"><div><b>'+esc(r.data.name)+'</b><small>'+esc(r.created_at)+'</small><div class="result">'+esc(r.data.text)+'</div></div></div>').join(''):empty('Запустите проверку, чтобы увидеть результат.'))+'</section>'}
async function saveAutomation(ev,task){ev.preventDefault();let b=ev.target.querySelector('button');b.disabled=true;try{await api('automation_save',{task,hour:Number(ev.target.hour.value),enabled:ev.target.enabled.checked});await reload();render();toast('Расписание сохранено')}catch(e){toast(e.message);b.disabled=false}}
async function runAutomation(id,b){b.disabled=true;try{await api('automation_run',{id});await reload();render();toast('Проверка выполнена')}catch(e){toast(e.message);b.disabled=false}}

function opportunitiesPage(){const stock=state.stock_batches||[],cap=state.business_capacity||[],signals=state.business_signals||[],drafts=state.promotion_drafts||[];return head('Риски, остатки и умные акции','Сроки партий, свободные ресурсы и решения с расчётом маржи.','<div class="actions" style="margin:0"><button class="btn light" onclick="openSmartImport(\'stock_batches\')">Импорт ресурсов</button><button class="btn light" onclick="openResource(\'stock_batches\')">＋ Партия / остаток</button><button class="btn" onclick="openResource(\'business_capacity\')">＋ Свободные места / часы</button></div>')+'<div class="notice">Остатки здесь — физическое наличие, отдельно от продаж в каталоге. Срок и условия хранения указывает владелец. Просроченное не включается в акции. Публикация не подтверждает заказ и не списывает остаток автоматически.</div><div class="grid stats">'+[['Партий',stock.length],['Срок истёк',signals.filter(x=>x.signal==='expired').length],['Близкий срок',signals.filter(x=>x.signal==='expiry').length],['Свободные ресурсы',cap.length]].map(x=>'<div class="stat"><label>'+x[0]+'</label><strong>'+x[1]+'</strong></div>').join('')+'</div><section class="card"><h2>Что требует внимания</h2>'+(signals.length?signals.map(s=>'<div class="row"><div><b>'+esc(s.name)+'</b><small>'+esc(s.title)+'</small></div><span class="badge '+(s.signal==='expired'?'pending':'')+'">'+(s.signal==='expired'?'Исключить из продажи':s.eligible?'Можно рассмотреть предложение':'Проверить')+'</span></div>').join(''):empty('Добавьте реальные партии и свободные места. Сигналы появятся по вашим данным.'))+'</section><section class="card" style="margin-top:20px"><h2>Придумать акции с ИИ</h2><p>ИИ предлагает механику, текст и шаги запуска. Сервер рассчитывает цену с учётом положительной себестоимости и минимальной валовой маржи. Учитываются остатки с близким сроком, долго хранящиеся партии и свободные места на ближайшие 7 дней. Условия хранения партии должны быть подтверждены.</p><form onsubmit="generatePromotions(event)"><div class="fields">'+field('margin','Минимальная валовая маржа, %','number','20','min="0" max="90" step="1" required')+'</div><div class="actions"><button class="btn" type="submit">✳ Подготовить идеи</button><a class="btn light" href="#automations">Настроить автоматическое создание</a></div></form></section><div class="sectiontitle"><h2>Предложения и черновики</h2></div><div class="grid twocol">'+drafts.map(d=>'<section class="card"><span class="badge">'+(d.data.status==='published'?'Опубликовано в боте':'Черновик — не опубликован')+'</span><h2 style="margin-top:12px">'+esc(d.data.name)+'</h2><p>'+esc(d.data.mechanic)+'</p><div class="row"><b>'+esc(d.data.item)+'</b><b>'+money(d.data.offer_price)+'</b></div><p class="hint">Обычная цена: '+money(d.data.original_price)+' · Скидка: '+esc(d.data.discount_percent)+'%<br>Валовая маржа: '+esc(d.data.gross_margin_percent)+'% · До '+esc(d.data.valid_until)+' · Лимит: '+esc(d.data.quantity_limit)+'</p><div class="result">'+esc(d.data.copy)+'</div><ul class="checklist">'+(d.data.steps||[]).map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul><div class="actions">'+(d.data.status!=='published'?'<button class="btn small" onclick="reviewPromotion('+d.id+')">Проверить и опубликовать в боте</button>':'')+'<button class="btn light small" onclick="promotionTask('+d.id+')">Создать задачу</button><button class="btn light small" onclick="archiveRecord('+d.id+')">В архив / снять</button></div></section>').join('')+'</div><section class="card" style="margin-top:24px"><h2>Партии и остатки</h2>'+resourceTable(stock,'stock_batches')+'</section><section class="card" style="margin-top:24px"><h2>Свободные ресурсы</h2><p>Места в группе, часы мастера, вместимость рейса или свободная дата зала. Для планирования; фактическую запись подтверждает сотрудник.</p>'+resourceTable(cap,'business_capacity')+'</section>'}
function resourceTable(rows,kind){return rows.length?'<div class="tablewrap"><table><thead><tr><th>Название</th><th>Остаток / места</th><th>Дата / срок</th><th>Цена / себестоимость</th><th></th></tr></thead><tbody>'+rows.map(r=>'<tr><td class="wrap"><b>'+esc(r.data.name)+'</b><small>'+esc(r.data.batch||r.data.note||'')+'</small></td><td>'+esc(r.data.quantity)+' '+esc(r.data.unit)+'</td><td>'+esc(r.data.expires_on||r.data.date||'Без срока')+(kind==='stock_batches'?'<br><small>'+(r.data.condition==='safe'?'Условия подтверждены':'Условия не подтверждены')+'</small>':'')+'</td><td>'+money(r.data.price)+' / '+money(r.data.cost)+'</td><td><button class="btn light small" onclick="openResource(\''+kind+'\','+r.id+')">Изменить</button> <button class="btn light small" onclick="archiveRecord('+r.id+')">В архив</button></td></tr>').join('')+'</tbody></table></div>':empty('Записей пока нет.')}
function openResource(kind,id=0){const r=(state[kind]||[]).find(x=>Number(x.id)===id)?.data||{},stock=kind==='stock_batches';modal(stock?'Партия и срок хранения':'Свободный ресурс','<form onsubmit="saveResource(event,\''+kind+'\','+id+')"><div class="fields">'+field('name','Название','text',r.name||'','required maxlength="180"')+opsResourceItemField(r,stock)+field('quantity','Фактический остаток / свободные места','number',r.quantity??'','required min="0" step="0.001"')+field('unit','Единица','text',r.unit||'шт.','required')+field('price','Обычная цена за единицу, ₸','number',r.price??'','min="0" step="0.01" required')+field('cost','Себестоимость единицы, ₸','number',r.cost??'','min="0" step="0.01" required')+(stock?field('batch','Номер партии','text',r.batch||'')+field('received_on','Дата поступления','date',r.received_on||today(),'required')+field('expires_on','Годен до (если применимо)','date',r.expires_on||'')+field('min_stock','Минимальный остаток','number',r.min_stock??'0','min="0" step="0.001" required')+'<div class="field"><label for="resourceCondition">Состояние и хранение</label><select name="condition" id="resourceCondition"><option value="blocked">Требует проверки — не включать в акции</option><option value="safe" '+(r.condition==='safe'?'selected':'')+'>Подтверждаю пригодность и условия хранения</option></select></div>':field('date','Дата свободного ресурса','date',r.date||today(),'required')+textfield('note','Примечание','Например, мастер, время или группа',r.note||''))+'</div><p class="hint">При неизвестной себестоимости можно указать 0, но автоматическая ценовая акция не будет рассчитана. Для скоропортящихся продуктов укажите реальный срок. Пригодность не определяется только по дате.</p><div class="actions"><button class="btn" type="submit">Сохранить</button></div></form>')}
async function saveResource(ev,kind,id){ev.preventDefault();let b=ev.target.querySelector('button');b.disabled=true;try{await api('resource_save',{kind,id,data:formData(ev.target)});$('modal').close();await reload();render();toast('Ресурс сохранён')}catch(e){toast(e.message);b.disabled=false}}
async function generatePromotions(ev){ev.preventDefault();let b=ev.target.querySelector('button');b.disabled=true;b.textContent='Готовим идеи…';try{await api('promotion_generate',{margin:Number(ev.target.margin.value)});await reload();render();toast('Черновики подготовлены')}catch(e){toast(e.message)}finally{b.disabled=false;b.textContent='✳ Подготовить идеи'}}
function reviewPromotion(id){let d=state.promotion_drafts.find(x=>Number(x.id)===id)?.data;if(!d)return;modal('Публикация предложения в Telegram-боте','<p>Клиенты смогут узнать об этой акции, когда обращаются к вашему боту. Рассылка не отправляется.</p><h3>'+esc(d.name)+'</h3><p>'+esc(d.copy)+'</p><p><b>'+esc(d.item)+' — '+money(d.offer_price)+'</b><br>До '+esc(d.valid_until)+' · Не более '+esc(d.quantity_limit)+' единиц.</p><p class="hint">Проверьте текст, наличие, состояние товара и условия. При изменении данных публикация будет повторно проверена.</p><div class="actions"><button class="btn" onclick="publishPromotion('+id+',this)">Подтвердить публикацию</button><button class="btn light" onclick="$(\'modal\').close()">Отмена</button></div>')}
async function publishPromotion(id,b){b.disabled=true;try{await api('promotion_publish',{id});$('modal').close();await reload();render();toast('Акция доступна в боте')}catch(e){toast(e.message);b.disabled=false}}
async function promotionTask(id){try{await api('promotion_task',{id});await reload();toast('Задача добавлена в ИИ-агент → задачи')}catch(e){toast(e.message)}}
function sectorPage(){const kit=state.sector_kit||{title:'Ваш бизнес',ideas:[]};return head('Инструменты: '+kit.title,'Сценарии и ресурсы под вашу сферу деятельности.')+'<div class="grid twocol"><section class="card"><h2>Возможности вашей отрасли</h2>'+kit.ideas.map(x=>'<div class="row"><b>'+esc(x)+'</b><button class="btn light small" onclick="sectorAgent(\''+esc(x)+'\')">Разработать план</button></div>').join('')+'<div class="actions"><a class="btn" href="#opportunities">Риски и акции</a><a class="btn light" href="#settings">Изменить сферу бизнеса</a></div></section><section class="card"><h2>С чего начать</h2><button class="btn light" onclick="openCatalogStarter()">Добавить пример каталога моей сферы</button><p>'+(kit.stock?'Добавьте фактические остатки и партии, сроки и себестоимость. ':'')+'Внесите свободные часы, места или мощность на ближайшие даты. ИИ сможет предложить варианты загрузки и акции по реальным ресурсам.</p><p>У каждого аккаунта отдельные данные. Новые идеи сохраняются как план или черновик; изменение данных и публикация требуют проверки.</p><div class="actions">'+(kit.stock?'<button class="btn light" onclick="openResource(\'stock_batches\')">Добавить партию</button>':'')+'<button class="btn" onclick="openResource(\'business_capacity\')">Добавить свободный ресурс</button></div></section></div>'}
function sectorAgent(topic){sessionStorage.setItem('aulieata.agentPrompt','Разработай практичный план для моей сферы: '+topic+'. Используй реальные данные моего бизнеса; если данных нет, уточни их. Предложи задачи для команды.');location.hash='agent'}

